CREATE DATABASE  IF NOT EXISTS `webshop_db`;
USE `webshop_db`;

DROP TABLE IF EXISTS `customer`;

CREATE TABLE `customer` (
  `customer_id` int NOT NULL,
  `username` varchar(45) NOT NULL,
  `password` varchar(45) NOT NULL,
  PRIMARY KEY (`customer_id`),
  UNIQUE KEY `username_UNIQUE` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `orders`;

CREATE TABLE `orders` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `order_date` varchar(45) NOT NULL,
  `total_price` float NOT NULL DEFAULT '0',
  `customer_id` int NOT NULL,
  PRIMARY KEY (`order_id`),
  KEY `customer_id_idx` (`customer_id`),
  CONSTRAINT `customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `payments`;

CREATE TABLE `payments` (
  `payment_id` int NOT NULL AUTO_INCREMENT,
  `date_paid` datetime NOT NULL,
  `order_id` int DEFAULT NULL,
  PRIMARY KEY (`payment_id`),
  KEY `order_id_idx` (`order_id`),
  CONSTRAINT `order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `product`;

CREATE TABLE `products` (
  `product_id` VARCHAR(20) NOT NULL,
  `description` VARCHAR(45) NOT NULL,
  `price` FLOAT NOT NULL,
  PRIMARY KEY (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `review`;

CREATE TABLE `reviews` (
  `review_id` VARCHAR(45) NOT NULL,
  `rating` FLOAT NOT NULL,
  `customer_id` INT NOT NULL,
  `product_id` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`review_id`),
  KEY `product_id_review_idx` (`product_id`),
  KEY `customer_id_review_idx` (`customer_id`),
  CONSTRAINT `customer_id_review` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`),
  CONSTRAINT `product_id_review` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;



DROP TABLE IF EXISTS `order_lines`;

CREATE TABLE `order_lines` (
  `order_id` INT NOT NULL,
  `product_id` VARCHAR(20) NOT NULL,
  `quantity` INT NOT NULL,
  `price` FLOAT NOT NULL,
  PRIMARY KEY (`order_id`, `product_id`),
  KEY `product_id_idx` (`product_id`),
  CONSTRAINT `order_id_lines` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`),
  CONSTRAINT `product_id` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- Triggers:

DELIMITER $$

CREATE TRIGGER set_order_dateset_created_atset_order_date
BEFORE INSERT ON orders
FOR EACH ROW 
BEGIN
    IF NEW.order_date IS NULL THEN
		SET NEW.order_date = NOW();
	END IF;
END $$

DELIMITER ;

DELIMITER $$

CREATE TRIGGER set_date_paid
BEFORE INSERT ON payments
FOR EACH ROW 
BEGIN
    IF NEW.date_paid IS NULL THEN
		SET NEW.date_paid = NOW();
	END IF;
END $$

DELIMITER ;

DELIMITER $$
USE webshop_db$$
CREATE TRIGGER update_order_total_price
AFTER INSERT ON order_lines
FOR EACH ROW
BEGIN 
	UPDATE orders
    SET total_price = (
		SELECT IFNULL(SUM(ol.price * ol.quantity), 0)
        FROM order_lines ol
        WHERE ol.order_id = NEW.order_id
    )
    WHERE order_id = NEW.order_id;
END$$
DELIMITER ;

DELIMITER $$
USE webshop_db$$
CREATE TRIGGER update_order_total_price_update
AFTER UPDATE ON order_lines
FOR EACH ROW
BEGIN 
	UPDATE orders
    SET total_price = (
		SELECT IFNULL(SUM(ol.price * ol.quantity), 0)
        FROM order_lines ol
        WHERE ol.order_id = NEW.order_id
    )
    WHERE order_id = NEW.order_id;
END$$
DELIMITER ;

DELIMITER $$
USE webshop_db$$
CREATE TRIGGER update_order_total_price_delete
AFTER DELETE ON order_lines
FOR EACH ROW
BEGIN 
	UPDATE orders
    SET total_price = (
		SELECT IFNULL(SUM(ol.price * ol.quantity), 0)
        FROM order_lines ol
        WHERE ol.order_id = OLD.order_id
    )
    WHERE order_id = OLD.order_id;
END$$
DELIMITER ;

-- Stored Procedures:

DROP procedure IF EXISTS `pagination`;

DELIMITER $$
USE `webshop_db`$$
CREATE PROCEDURE pagination(
	IN size INT,
    IN anchor_id varchar(45),
    IN search_filter varchar(45),
    IN direction ENUM('next', 'prev')
)
BEGIN
	IF direction = 'next' THEN
		SELECT * FROM products as p
		WHERE p.description LIKE CONCAT('%', search_filter, '%') 
			AND (anchor_id IS NULL OR p.product_id > anchor_id)
		ORDER BY p.product_id ASC
		LIMIT size;
	ELSE
		SELECT * FROM products as p
		WHERE p.description LIKE CONCAT('%', search_filter, '%') 
			AND (anchor_id IS NULL OR p.product_id < anchor_id)
		ORDER BY p.product_id ASC
		LIMIT size;
	END IF;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS create_order_with_line;

DELIMITER $$
USE `webshop_db`$$
CREATE PROCEDURE create_order_with_line(
    IN p_customer_id INT,
    IN p_product_id VARCHAR(20),
    IN p_quantity INT,
    IN p_price FLOAT,
    INOUT p_order_id INT
)
BEGIN
    IF p_order_id = 0 THEN
        INSERT INTO orders (customer_id) VALUES (p_customer_id);
        SET p_order_id = LAST_INSERT_ID();
    END IF;
    INSERT INTO order_lines (order_id, product_id, quantity, price)
    VALUES (p_order_id, p_product_id, p_quantity, p_price);
END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS create_payment;

DELIMITER $$
USE `webshop_db`$$
CREATE PROCEDURE create_payment(IN p_order_id INT)
BEGIN
    INSERT INTO payments (order_id)
    VALUES (p_order_id);
END$$

DELIMITER ;



-- Views

use webshop_db;

CREATE OR REPLACE VIEW unpaid_orders_view AS
SELECT o.order_id, o.order_date, o.total_price, o.customer_id
FROM orders o
LEFT JOIN payments p ON o.order_id = p.order_id
WHERE p.payment_id IS NULL;


use webshop_db;

CREATE OR REPLACE VIEW paid_orders_view AS
SELECT o.order_id, o.order_date, o.total_price, o.customer_id, p.date_paid
FROM orders o
JOIN payments p ON o.order_id = p.order_id;

